    ('fa245dcb-9b81-40b2-b221-b670d983549c'::uuid, 'United Kingdom', 'Northern Ireland', 'country-uk-part:fa245dcb-9b81-40b2-b221-b670d983549c', 'country-uk-part (geo-unit): ''United Kingdom'' -> ''Northern Ireland'' (ISO GB -> GB); witnesses: P17', '54.993700213683596,-6.478501487221294', '[{"source": "naturalearth:ne_10m_admin_0_map_units (GEOUNIT=Northern Ireland)", "url": "https://naciscdn.org/naturalearth/10m/cultural/ne_10m_admin_0_map_units.zip", "retrieved_at": "2026-09-22T21:40:07+00:00", "quote": "point (54.99370, -6.47850) inside the ''Northern Ireland'' geo unit"}, {"source": "pipeline/utils/country_lookup.py:NAME_TO_ISO / normalize_country", "url": "pipeline/utils/country_lookup.py", "quote": "normalize_country(''United Kingdom'') = ''GB''; normalize_country(''Northern Ireland'') = ''GB''"}, {"source": "ancient-nerds-map/src/utils/countryFlags.ts:COUNTRY_CODES", "url": "ancient-nerds-map/src/utils/countryFlags.ts", "quote": "COUNTRY_CODES[''Northern Ireland''] = ''GB''"}, {"source": "wikidata:Q1235918:P625", "url": "https://www.wikidata.org/entity/Q1235918", "retrieved_at": "2026-09-22T21:44:46+00:00", "quote": "P625 (54.9936, -6.47854) inside the ''Northern Ireland'' geo unit"}, {"source": "wikidata:Q1235918:P17 -> Q145:P297", "url": "https://www.wikidata.org/entity/Q1235918", "retrieved_at": "2026-09-22T21:44:46+00:00", "quote": "Q1235918 P17 only: Q145 United Kingdom (GB) -> ISO 3166-1 alpha-2 GB (''United Kingdom''); anchor via site_external_ids:wikidata_qid"}, {"source": "remediation_change_log:28662", "url": "remediation_change_log", "quote": "phase3:batch-0176:chunk-0001 (P3/country): ''Ireland'' -> ''United Kingdom'' - the value this lane supersedes"}, {"source": "output/remediation/HANDOVER.md:103", "url": "output/remediation/HANDOVER.md", "quote": "2. The United Kingdom''s parts are spelled by region: **`Northern Ireland`**, not `United Kingdom`."}, {"source": "output/remediation/HUMAN_ONLY.md:49 (B9)", "url": "output/remediation/HUMAN_ONLY.md